  <div class="analytics-grid wide"><article class="card chart-panel">${sectionTitle('比赛表现',`<div class="chart-switch" role="group" aria-label="表现指标">${[['adr','ADR'],['kast_pct','KAST'],['kd','K/D']].map(([key,label])=>`<button type="button" data-trend="${key}" aria-pressed="${metric===key}">${label}</button>`).join('')}</div>`)}${lineChart([{name:metric==='adr'?'ADR':metric==='kd'?'K/D':'KAST',color:palette.mint,data:trend.map((match,i)=>({x:i+1,y:aggregate(match.filteredRounds)[metric]}))}],{title:'逐场比赛表现',xLabel:'比赛顺序',integerX:true,yLabel:metric==='adr'?'ADR':metric==='kd'?'K/D':'KAST / %',maxY:metric==='kast_pct'?100:undefined})}<div class="trend-match-labels">${trend.map((match,i)=>`<button type="button" data-open-match="${esc(match.match_id)}"><span class="trend-index">${String(i+1).padStart(2,'0')}</span><strong>${esc(mapName(match.map_name))}</strong><small>${esc(match.match_time_verified?dayKey(match.match_started_at)?.slice(5):'未标注日期')}</small></button>`).join('')}</div></article><article class="card">${sectionTitle('阵营对比',`<span class="micro-label">CT / T</span>`)}${['CT','T'].map(side=>{const a=aggregate(scope.rounds.filter(round=>round.side===side));return `<div class="side-analysis ${side.toLowerCase()}"><div><span class="side-token">${side}</span><span>${a.rounds} 回合</span><strong>${format(a.adr,1)}<small> ADR</small></strong></div><div class="side-stat-row"><span>K/D <b>${format(a.kd,2)}</b></span><span>KAST <b>${percent(a.kast_pct,1)}</b></span></div><div class="side-meter"><i style="width:${ratio(a.damage,Math.max(1,s.damage),100)||0}%"></i></div></div>`;}).join('')}<div class="side-total"><span>首杀</span><strong>${s.opening_kills}</strong><span>首死</span><strong>${s.opening_deaths}</strong></div></article></div>
