  <div class="analytics-grid two"><article class="card">${sectionTitle('关键事件',tag(`R${round.round_number}`,'blue'))}${eventTimeline(match,round)}</article><article class="card">${sectionTitle('交战与转化',`<span class="micro-label">${rounds.length} ROUNDS</span>`)}${compactTactics(match)}</article></div>
