document.addEventListener('click',event=>{
  const agentSection=event.target.closest('[data-coach-section]');if(agentSection){runCoachSection(agentSection.dataset.coachSection);return;}
  if(event.target.closest('[data-retry-statistics]')){statisticsError=null;render();return;}
  const retryMatch=event.target.closest('[data-retry-match]');if(retryMatch){matchDetailErrors.delete(detailKey(indexedMatch(retryMatch.dataset.retryMatch)?.detail_ref));render();return;}
  if(event.target.closest('[data-retry-aim]')){const clip=selectedAimWindow();if(clip?.trajectory_source)aimTrajectoryErrors.delete(clip.trajectory_source);updateAimFrame(clip);return;}
  if(event.target.closest('[data-retry-shots]')){const item=replayRound(currentMatch(),currentRound());if(item)replayShotErrors.delete(item);updatePath();return;}
  if(event.target.closest('[data-aim-open-replay]')){const clip=selectedAimWindow();if(clip){const tick=clip.points[state.aimPoint]?.tick??clip.tick;selectMatch(clip.match_id,'replay');state.roundNumber=clip.round_number;coachReplayTarget={match_id:clip.match_id,round_number:clip.round_number,tick};render();}return;}
  const aimView=event.target.closest('[data-aim-view]');if(aimView){stopAimPlayback();rememberAimView(selectedAimWindow(),aimView.dataset.aimView);$$('[data-aim-view]').forEach(button=>button.setAttribute('aria-pressed',String(button.dataset.aimView===state.aimView)));updateAimFrame();return;}
  const radarPlayer=event.target.closest('[data-radar-player]');if(radarPlayer){const index=Number(radarPlayer.dataset.radarPlayer);state.radarPlayer=state.radarPlayer===index?null:index;updatePath();return;}
  const shotStep=event.target.closest('[data-replay-shot-step]');if(shotStep){const match=currentMatch(),round=currentRound(match),item=replayRound(match,round),shots=replayShots(item),model=playbackModel(match,round),tick=model.frames[state.positionIndex]?.[0]??round.start_tick,index=shots.findIndex(shot=>shot.id===state.selectedShotId),next=index>=0?Math.max(0,Math.min(shots.length-1,index+Number(shotStep.dataset.replayShotStep))):Number(shotStep.dataset.replayShotStep)>0?shots.findIndex(shot=>shot.tick>=tick):Math.max(0,shots.findLastIndex(shot=>shot.tick<=tick));if(shots[next])jumpToShot(shots[next].id);return;}
  const shot=event.target.closest('[data-replay-shot]');if(shot){jumpToShot(shot.dataset.replayShot);return;}

  const go=event.target.closest('[data-go-view]');if(go){location.hash=go.dataset.goView;navigate(go.dataset.goView);return;}
  const tactical=event.target.closest('[data-tactical-id]');if(tactical){jumpToTactical(Number(tactical.dataset.tacticalTick),tactical.dataset.tacticalId);return;}
  const layer=event.target.closest('[data-tactical-layer]');if(layer){state.effectLayers[layer.dataset.tacticalLayer]=!state.effectLayers[layer.dataset.tacticalLayer];layer.setAttribute('aria-pressed',String(state.effectLayers[layer.dataset.tacticalLayer]));updatePath();return;}
  const aimStep=event.target.closest('[data-aim-step]');if(aimStep){stopPlayback();state.aimIndex=Math.max(0,state.aimIndex+Number(aimStep.dataset.aimStep));state.aimPoint=0;state.aimReference='auto';render();return;}
  const aimTick=event.target.closest('[data-aim-tick]');if(aimTick){stopAimPlayback();const clip=selectedAimWindow();if(clip){rememberAimView(clip,state.aimView);const tick=Number(aimTick.dataset.aimTick),index=clip.points.findIndex(point=>point.tick>=tick);state.aimPoint=index>=0?index:clip.points.length-1;updateAimFrame(clip);}return;}
  if(event.target.closest('#play-aim')){if(state.aimPlaying)stopAimPlayback();else startAimPlayback();return;}
  const labtab=event.target.closest('[data-lab-tab]');if(labtab){state.labTab=labtab.dataset.labTab;render();return;}
  const labscope=event.target.closest('[data-lab-scope]');if(labscope){state.labScope=labscope.dataset.labScope;state.labWeapon='all';state.targetIndex=state.stopIndex=state.sprayIndex=state.aimIndex=state.aimPoint=0;state.aimReference='auto';render();return;}
  const labweapon=event.target.closest('[data-lab-weapon]');if(labweapon){state.labWeapon=labweapon.dataset.labWeapon;state.targetIndex=state.stopIndex=state.sprayIndex=state.aimIndex=state.aimPoint=0;state.aimReference='auto';render();return;}
  const trend=event.target.closest('[data-trend]');if(trend){state.trendMetric=trend.dataset.trend;render();return;}
  const mapFilter=event.target.closest('[data-filter-map]');if(mapFilter){state.map=mapFilter.dataset.filterMap;$('#map-filter').value=state.map;state.roundNumber=null;render();return;}
  const target=event.target.closest('[data-target-index]');if(target){state.targetIndex=Number(target.dataset.targetIndex);render();return;}
  const stop=event.target.closest('[data-stop-index]');if(stop){state.stopIndex=Number(stop.dataset.stopIndex);render();return;}
  const spray=event.target.closest('[data-spray-index]');if(spray){state.sprayIndex=Number(spray.dataset.sprayIndex);render();return;}
  const replay=event.target.closest('[data-open-replay]');if(replay){selectMatch(replay.dataset.openReplay,'replay');if(replay.dataset.roundTarget)selectRound(Number(replay.dataset.roundTarget));return;}
  const nav=event.target.closest('[data-view]');if(nav){navigate(nav.dataset.view,true);return;}
  const match=event.target.closest('[data-open-match]');if(match){selectMatch(match.dataset.openMatch);return;}
  const spatial=event.target.closest('[data-spatial]');if(spatial){state.spatialMode=spatial.dataset.spatial;state.positionIndex=0;state.selectedKillId=null;stopPlayback();cancelReplayDecode();render();return;}
  const round=event.target.closest('[data-round]');if(round){selectRound(Number(round.dataset.round));return;}
  const evidence=event.target.closest('[data-evidence]');if(evidence){const match=evidence.dataset.evidence.match(/^(.+):r(\d+)$/);if(match){selectMatch(match[1]);selectRound(Number(match[2]));}return;}
  if(event.target.closest('[data-action="reset"]')){resetFilters();return;}
  const kill=event.target.closest('[data-kill]');if(kill){jumpToKill(kill.dataset.kill);return;}
  if(event.target.closest('[data-retry-replay]')){const item=replayRound(currentMatch(),currentRound());if(item)replayErrors.delete(item);updatePath();return;}
  const play=event.target.closest('#play-path');if(play){if(state.playing)stopPlayback();else startPlayback();return;}
});
document.addEventListener('change',event=>{if(event.target.id==='replay-shot-select'){jumpToShot(event.target.value);return;}if(event.target.id==='aim-reference'){state.aimReference=event.target.value;render();return;}if(event.target.id==='aim-outcome'){state.aimOutcome=event.target.value;state.aimIndex=state.aimPoint=0;state.aimReference='auto';render();return;}if(event.target.id==='aim-speed'){const resume=state.aimPlaying;stopAimPlayback();state.aimSpeed=Number(event.target.value);if(resume)startAimPlayback();return;}if(event.target.id==='lab-weapon'){state.labWeapon=event.target.value;state.targetIndex=state.stopIndex=state.sprayIndex=state.aimIndex=state.aimPoint=0;state.aimReference='auto';render();return;}if(event.target.dataset.burstKind){state[({target:'targetIndex',stop:'stopIndex',spray:'sprayIndex',aim:'aimIndex'})[event.target.dataset.burstKind]]=Number(event.target.value);if(event.target.dataset.burstKind==='aim'){state.aimPoint=0;state.aimReference='auto';}render();return;}if(event.target.id==='playback-speed'){const resume=state.playing;stopPlayback();state.playbackSpeed=Number(event.target.value);if(resume)startPlayback();return;}if(event.target.id==='crosshair-window'){state.crosshairIndex=Number(event.target.value);render();return;}if(event.target.matches('.match-selector'))selectMatch(event.target.value,state.view);});
document.addEventListener('input',event=>{if(event.target.id==='aim-scrubber'){stopAimPlayback();rememberAimView(selectedAimWindow(),'angles');state.aimPoint=Number(event.target.value);updateAimFrame();return;}if(event.target.id==='position-scrubber'){stopPlayback();state.selectedKillId=null;state.selectedShotId=null;state.positionIndex=Number(event.target.value);const play=$('#play-path');if(play){play.textContent='▶';play.setAttribute('aria-label','播放位置采样');}updatePath();}});
